"""EfficientNet-B0 baseline on a Kaggle GPU (the baseline required by SRS section 4.2).

Fair comparison with our CLIP-based model v3: it is trained on the SAME OpenFake training images (same image ids,
embedded below) and scored on the SAME held-out OpenFake test images (3,392 images, generators never seen in
training) in the same three variants (clean, JPEG 70, half size + JPEG 75).

Recipe (fixed beforehand, nothing tuned on the test images): ImageNet-pretrained EfficientNet-B0 (timm), whole image
resized to 224 x 224, random horizontal flip, AdamW lr 2e-4, weight decay 0.01, batch 64, 3 epochs, cosine schedule,
mixed precision. Outputs: preds.csv (one row per test image and variant) and result.json.
"""
import base64, io, json, os, random, subprocess, sys, time, zlib
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor, wait, FIRST_COMPLETED

subprocess.run([sys.executable, "-m", "pip", "install", "-q", "huggingface_hub", "pyarrow", "timm"], check=False)

import numpy as np
import pyarrow.parquet as pq
import torch
import torch.nn.functional as F
from PIL import Image

OUT = "/kaggle/working"
SIZE, WORKERS, EPOCHS, BATCH, LR = 224, 6, 3, 64, 2e-4
LOAD_BUDGET = 4.5 * 3600            # seconds; if loading takes longer we train on the images loaded so far (and say so)
IDS_B64 = ""                 # filled in by kaggle/make_payload.py

try:
    from kaggle_secrets import UserSecretsClient
    _c, _t = UserSecretsClient(), None
    for _l in ("HF_TOKEN", "HF_Token", "hf_token"):
        try:
            _t = _c.get_secret(_l)
            break
        except Exception:
            continue
    if _t:
        os.environ["HF_TOKEN"] = _t
        print("HF token found", flush=True)
except Exception:
    pass

from huggingface_hub import HfFileSystem
fs = HfFileSystem()
ids = json.loads(zlib.decompress(base64.b64decode(IDS_B64)))


def retry(fn, tries=5):
    for i in range(tries):
        try:
            return fn()
        except Exception:
            if i == tries - 1:
                raise
            time.sleep(2 * (i + 1) + random.random())


def jpeg_rt(img, q):
    buf = io.BytesIO()
    img.save(buf, "JPEG", quality=int(q))
    return Image.open(io.BytesIO(buf.getvalue())).convert("RGB")


def variant(img, name):
    if name == "clean":
        return img
    if name == "jpeg70":
        return jpeg_rt(img, 70)
    return jpeg_rt(img.resize((max(32, img.width // 2), max(32, img.height // 2)), Image.BICUBIC), 75)    # half_q75


def to_arr(img):
    return np.asarray(img.resize((SIZE, SIZE), Image.BICUBIC))


def plan(split, pattern):
    paths = {os.path.basename(p): p for p in fs.glob(pattern)}
    by = defaultdict(list)
    for iid in ids[split]:
        fn, rg, r = iid.rsplit(":", 2)
        by[(paths[fn], int(rg))].append((iid, int(r)))
    return sorted(by.items())


def read_group(task, variants):
    (fp, rg), rows = task

    def go():
        with fs.open(fp, "rb") as f:
            return pq.ParquetFile(f).read_row_group(rg, columns=["image", "label", "model"])
    t = retry(go)
    imgs, labels, models = t.column("image").to_pylist(), t.column("label").to_pylist(), t.column("model").to_pylist()
    out = []
    for iid, r in rows:
        try:
            img = Image.open(io.BytesIO(imgs[r]["bytes"]))
            img.load()
            img = img.convert("RGB")
            out.append((iid, int(labels[r] != "real"), "real" if labels[r] == "real" else models[r],
                        [to_arr(variant(img, v)) for v in variants]))
        except Exception as e:
            print("skip", iid, repr(e)[:80], flush=True)
    return out


def load(split, pattern, variants, deadline):
    tasks = plan(split, pattern)
    print(f"[{split}] {len(tasks)} row groups for {len(ids[split])} images", flush=True)
    res, t0, done = [], time.time(), 0
    with ThreadPoolExecutor(WORKERS) as ex:
        pending, it, exhausted = set(), iter(tasks), False
        while pending or not exhausted:
            while not exhausted and len(pending) < WORKERS + 2:
                if time.time() > deadline:
                    print(f"[{split}] load budget reached; using what is loaded", flush=True)
                    exhausted = True
                    break
                try:
                    pending.add(ex.submit(read_group, next(it), variants))
                except StopIteration:
                    exhausted = True
            if not pending:
                break
            fin, pending = wait(pending, return_when=FIRST_COMPLETED)
            for fu in fin:
                try:
                    res.extend(fu.result())
                except Exception as e:
                    print("group failed:", repr(e)[:100], flush=True)
                done += 1
                if done % 20 == 0:
                    print(f"[{split}] {done}/{len(tasks)} groups, {len(res)} images, {time.time()-t0:.0f}s", flush=True)
    return res


T0 = time.time()
test = load("test", "datasets/ComplexDataLab/OpenFake/core/test-*.parquet", ["clean", "jpeg70", "half_q75"], T0 + 3600)
train = load("train", "datasets/ComplexDataLab/OpenFake/core/train-*.parquet", ["clean"], time.time() + LOAD_BUDGET)
print(f"loaded {len(train)} train and {len(test)} test images in {time.time()-T0:.0f}s", flush=True)

Xtr = torch.from_numpy(np.stack([a[3][0] for a in train]))             # N x H x W x 3, uint8
ytr = torch.tensor([a[1] for a in train], dtype=torch.float32)
print("train label share fake:", float(ytr.mean()), flush=True)

import timm
model = timm.create_model("efficientnet_b0.ra_in1k", pretrained=True, num_classes=1).cuda()
MEAN = torch.tensor([0.485, 0.456, 0.406], device="cuda").view(1, 3, 1, 1)
STD = torch.tensor([0.229, 0.224, 0.225], device="cuda").view(1, 3, 1, 1)


def prep(xb):
    return ((xb.cuda(non_blocking=True).permute(0, 3, 1, 2).float() / 255.0) - MEAN) / STD


opt = torch.optim.AdamW(model.parameters(), lr=LR, weight_decay=0.01)
steps = EPOCHS * (len(Xtr) // BATCH)
sched = torch.optim.lr_scheduler.OneCycleLR(opt, max_lr=LR, total_steps=steps, pct_start=0.1)
scaler = torch.cuda.amp.GradScaler()
step = 0
for ep in range(EPOCHS):
    model.train()
    perm = torch.randperm(len(Xtr))
    tot = 0.0
    for i in range(0, len(perm) - BATCH + 1, BATCH):
        idx = perm[i:i + BATCH]
        x, y = prep(Xtr[idx]), ytr[idx].cuda()
        flip = torch.rand(len(x), device="cuda") < 0.5
        x = torch.where(flip.view(-1, 1, 1, 1), x.flip(3), x)
        with torch.autocast("cuda", dtype=torch.float16):
            loss = F.binary_cross_entropy_with_logits(model(x).squeeze(1).float(), y)
        opt.zero_grad(set_to_none=True)
        scaler.scale(loss).backward()
        scaler.step(opt)
        scaler.update()
        if step < steps - 1:
            sched.step()
        step += 1
        tot += float(loss)
        if step % 100 == 0:
            print(f"epoch {ep+1} step {step}/{steps} loss {tot/((i//BATCH)+1):.4f}", flush=True)
    print(f"epoch {ep+1} done, mean loss {tot/(len(perm)//BATCH):.4f}, {time.time()-T0:.0f}s", flush=True)

model.eval()
rows = []
with torch.no_grad():
    for vi, vname in enumerate(["clean", "jpeg70", "half_q75"]):
        X = torch.from_numpy(np.stack([a[3][vi] for a in test]))
        logits = []
        for i in range(0, len(X), 128):
            with torch.autocast("cuda", dtype=torch.float16):
                logits.append(model(prep(X[i:i + 128])).squeeze(1).float().cpu())
        logits = torch.cat(logits).numpy()
        for a, lg in zip(test, logits):
            rows.append((a[0], vname, a[2], a[1], float(lg)))

import csv
with open(f"{OUT}/preds.csv", "w", newline="") as f:
    wr = csv.writer(f)
    wr.writerow(["img_id", "variant", "src", "label", "logit"])
    wr.writerows(rows)

from sklearn.metrics import roc_auc_score
res = {"n_train": len(train), "n_test": len(test), "epochs": EPOCHS, "variants": {}}
for vname in ["clean", "jpeg70", "half_q75"]:
    r = [x for x in rows if x[1] == vname]
    y, s = np.array([x[3] for x in r]), np.array([x[4] for x in r])
    res["variants"][vname] = {"auc": round(float(roc_auc_score(y, s)), 4),
                              "real_correct": round(float((s[y == 0] < 0).mean()), 4),
                              "fake_caught": round(float((s[y == 1] > 0).mean()), 4)}
json.dump(res, open(f"{OUT}/result.json", "w"), indent=1)
print(json.dumps(res, indent=1), flush=True)
print("DONE in", round(time.time() - T0), "s", flush=True)
